begin;
do $test$
declare owner uuid; employee uuid; outsider uuid:=gen_random_uuid(); wid uuid:=gen_random_uuid(); wid2 uuid:=gen_random_uuid(); mail text; tid text; result jsonb; denied boolean; snapshot jsonb;
begin
 select id into owner from auth.users where email_confirmed_at is not null order by created_at limit 1;
 select id,email into employee,mail from auth.users where id<>owner and email_confirmed_at is not null order by created_at limit 1;
 if employee is null then raise exception 'Two confirmed accounts needed for rollback-only test'; end if;
 insert into public.opsfusion_workspaces(id,owner_id,name,state) values(wid,owner,'ROLLBACK ONLY portal test','{"identities":[{"id":"u1","displayName":"Portal Employee","username":"portal","upn":"portal@example.test","status":"Active"}],"endpoints":[],"assets":[],"incidents":[],"maintenance":[]}');
 insert into public.opsfusion_workspaces(id,owner_id,name,state) values(wid2,owner,'ROLLBACK ONLY other workspace','{"identities":[],"endpoints":[],"assets":[],"incidents":[]}');
 perform set_config('request.jwt.claim.sub',owner::text,true);
 perform public.opsfusion_employee_portal('grant',wid,jsonb_build_object('identity_id','u1','email',mail));
 perform set_config('request.jwt.claim.sub',employee::text,true);
 result:=public.opsfusion_employee_portal('workspaces');
 if not exists(select 1 from jsonb_array_elements(result) w where w->>'id'=wid::text) then raise exception 'Enrollment not visible'; end if;
 denied:=false;begin perform public.opsfusion_employee_portal('access_list',wid);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Employee accessed enrollment admin';end if;
 denied:=false;begin perform public.opsfusion_employee_portal('tickets',wid2);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Cross-workspace access accepted';end if;
 result:=public.opsfusion_employee_portal('create',wid,'{"title":"VPN is unavailable","description":"VPN cannot connect since this morning","portalUserId":"forged","priority":"P1","requesterId":"forged"}');tid:=result->>'ticket_id';
 result:=public.opsfusion_employee_portal('tickets',wid);
 if jsonb_array_length(result)<>1 or result->0->>'priority'<>'P3' or result->0 ? 'activities' or result->0 ? 'portalUserId' then raise exception 'Invalid ticket projection or forged fields accepted';end if;
 perform public.opsfusion_employee_portal('comment',wid,jsonb_build_object('ticket_id',tid,'body','The problem also occurs on Wi-Fi.'));
 result:=public.opsfusion_employee_portal('tickets',wid);
 if result->0->'messages'->0->>'author'<>'Employee' then raise exception 'Reply failed';end if;
 select state into snapshot from public.opsfusion_workspaces where id=wid;
 if snapshot->'incidents'->0->>'requesterId'<>'u1' or snapshot->'incidents'->0->>'portalUserId'<>employee::text then raise exception 'Server ownership not authoritative';end if;
 update public.opsfusion_workspaces set state=jsonb_set(state,'{incidents}',(state->'incidents')||jsonb_build_array(jsonb_build_object('id','INC-OTHER','portalUserId',outsider,'requesterId','u1','title','Private other request','status','New'))) where id=wid;
 result:=public.opsfusion_employee_portal('tickets',wid);
 if jsonb_array_length(result)<>1 then raise exception 'Another employee ticket leaked within same workspace';end if;
 denied:=false;begin perform public.opsfusion_employee_portal('comment',wid,'{"ticket_id":"INC-OTHER","body":"Forbidden reply"}');exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Employee replied to another ticket';end if;
 update public.opsfusion_workspaces set state=jsonb_set(state,'{incidents,0,status}','"Resolved"') where id=wid;
 result:=public.opsfusion_employee_portal('tickets',wid);
 if result->0->>'status'<>'Resolved' then raise exception 'Staff status not visible to employee';end if;
 denied:=false;begin perform public.opsfusion_employee_portal('comment',wid,jsonb_build_object('ticket_id',tid,'body','Closed reply'));exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'Resolved ticket accepted reply';end if;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 denied:=false;begin perform public.opsfusion_employee_portal('comment',wid,jsonb_build_object('ticket_id',tid,'body','Unauthorized'));exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Foreign employee reply accepted';end if;
 perform set_config('request.jwt.claim.sub',employee::text,true);
 -- Exercise actual authenticated grants and RLS, not only function checks.
 execute 'set local role authenticated';
 if exists(select 1 from public.opsfusion_workspaces where id=wid) then raise exception 'Employee can read raw workspace';end if;
 result:=public.opsfusion_employee_portal('tickets',wid);
 if jsonb_array_length(result)<>1 then raise exception 'Authorized RPC failed with authenticated role';end if;
 execute 'reset role';
 update public.opsfusion_workspaces set state=jsonb_set(state,'{identities,0,status}','"Disabled"') where id=wid;
 denied:=false;begin perform public.opsfusion_employee_portal('tickets',wid);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Disabled identity retained portal access';end if;
 update public.opsfusion_workspaces set state=jsonb_set(state,'{identities,0,status}','"Active"') where id=wid;
 perform set_config('request.jwt.claim.sub',owner::text,true);
 perform public.opsfusion_employee_portal('revoke',wid,'{"identity_id":"u1"}');
 perform set_config('request.jwt.claim.sub',employee::text,true);
 denied:=false;begin perform public.opsfusion_employee_portal('tickets',wid);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Revoked access accepted';end if;
 if has_function_privilege('anon','public.opsfusion_employee_portal(text,uuid,jsonb)','EXECUTE') or has_table_privilege('authenticated','public.opsfusion_employee_access','SELECT') then raise exception 'Excess grants';end if;
end $test$;
rollback;
select 'PASS: owner enrollment; employee-only projection; authoritative ticket ownership; replies; cross-workspace and foreign-user denial; raw workspace RLS; disabled identity and revocation; no anonymous execution. Fixtures rolled back.' verification;
